public class Main {
    String subStrHash(String s, int power, int modulo, int k, int hashValue) {
        int n = s.length();
        for (int start = 0; start <= n - k; start++) {
            long h = 0, p = 1;
            for (int i = 0; i < k; i++) {                                   // recompute the full polynomial from scratch
                long val = s.charAt(start + i) - 'a' + 1;
                h = (h + val * p) % modulo;
                p = (p * power) % modulo;
            }
            if (h == hashValue) return s.substring(start, start + k);
        }
        return "";
    }

    public static void main(String[] args) {
        String s = "fbxzaad";
        int power = 31;
        int modulo = 100;
        int k = 3;
        int hashValue = 32;
        Main solution = new Main();
        System.out.println(solution.subStrHash(s, power, modulo, k, hashValue));
    }
}

