public class Main {
    String subStrHash(String s, int power, int modulo, int k, int hashValue) {
        int n = s.length();
        long highPower = 1;
        for (int i = 0; i < k - 1; i++) highPower = (highPower * power) % modulo;

        long currentHash = 0;
        for (int i = n - 1; i >= n - k; i--) {
            long val = s.charAt(i) - 'a' + 1;
            currentHash = (currentHash * power + val) % modulo;               // build the very last window directly
        }
        int resultStart = (currentHash == hashValue) ? n - k : -1;
        for (int start = n - k - 1; start >= 0; start--) {
            long removeVal = s.charAt(start + k) - 'a' + 1;
            currentHash = ((currentHash - removeVal * highPower % modulo) % modulo + modulo) % modulo;
            long addVal = s.charAt(start) - 'a' + 1;
            currentHash = (currentHash * power + addVal) % modulo;               // roll left with only multiply and add
            if (currentHash == hashValue) resultStart = start;                     // keep overwriting, never stop early
        }
        return s.substring(resultStart, resultStart + k);
    }

    public static void main(String[] args) {
        String s = "fbxzaad";
        int power = 31;
        int modulo = 100;
        int k = 3;
        int hashValue = 32;
        Main solution = new Main();
        System.out.println(solution.subStrHash(s, power, modulo, k, hashValue));
    }
}

